import * as THREE from 'three/webgpu';
import {
  color,
  mix,
  uv,
  mul,
  add,
  float,
  vec2,
  vec3,
  ifThenElse,
  lessThan,
  greaterThan,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  group.name = config.id || 'kinetic-hero';

  // ---------- BACKDROP ----------
  const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
  const gradientNode = mix(
    color('#0b0b10'),
    color('#13131a'),
    uv().y
  );
  const backdropMat = new THREE.MeshStandardNodeMaterial({
    color: gradientNode,
    side: THREE.DoubleSide,
    transparent: false,
    metalness: 0,
    roughness: 1,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  group.add(backdrop);

  // ---------- TEXT HELPERS ----------
  const scaleFactor = 0.62 / 124; // hero em height to scene units
  const glyphMeshes = [];

  function createGlyphMesh(char, glyphInfo, pos, zOffset) {
    const geom = new THREE.PlaneGeometry(glyphInfo.size.x, glyphInfo.size.y);
    // Apply UVs
    const uvs = geom.attributes.uv.array;
    const { u, v, u2, v2 } = glyphInfo.uv;
    uvs[0] = u;   uvs[1] = v;
    uvs[2] = u2;  uvs[3] = v;
    uvs[4] = u;   uvs[5] = v2;
    uvs[6] = u2;  uvs[7] = v2;
    geom.attributes.uv.needsUpdate = true;

    const msdfNode = mix(
      color('#16161d'), // ink color
      color('#e8ecf2'), // paper fallback
      texture(ctx.fontAtlas.texture, uv())
    );

    const mat = new THREE.MeshStandardNodeMaterial({
      color: msdfNode,
      transparent: true,
      side: THREE.DoubleSide,
    });
    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.set(pos.x, pos.y, pos.z + zOffset);
    mesh.renderOrder = 1;
    return mesh;
  }

  // ---------- HERO TEXT ----------
  const heroSpec = {
    text: 'TIME, MACHINED.',
    yBase: 0.4,
    zOffsets: [0.12, 0, -0.12],
    fontSizePx: 124,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.05,
    family: 'Lora',
  };

  const heroGroup = new THREE.Group();
  const words = heroSpec.text.split(' ');
  let cursorX = 0;
  const wordZ = heroSpec.zOffsets;
  const glyphScale = scaleFactor;

  words.forEach((word, wIdx) => {
    const zOff = wordZ[wIdx] ?? 0;
    for (let i = 0; i < word.length; i++) {
      const ch = word[i];
      const glyphInfo = ctx.fontAtlas.getGlyph(ch, {
        size: heroSpec.fontSizePx,
        weight: heroSpec.fontWeight,
        family: heroSpec.family,
        atlas: 0,
      });
      const advance = glyphInfo.advance * glyphScale;
      const pos = {
        x: cursorX + glyphInfo.bearing.x * glyphScale,
        y: heroSpec.yBase,
        z: 0,
      };
      const mesh = createGlyphMesh(ch, glyphInfo, pos, zOff);
      mesh.material.opacity = 0;
      heroGroup.add(mesh);
      glyphMeshes.push(mesh);
      cursorX += advance + heroSpec.letterSpacing * glyphScale;
    }
    // add space advance
    const spaceInfo = ctx.fontAtlas.getGlyph(' ', {
      size: heroSpec.fontSizePx,
      weight: heroSpec.fontWeight,
      family: heroSpec.family,
      atlas: 0,
    });
    cursorX += spaceInfo.advance * glyphScale;
  });
  // Center hero group horizontally
  heroGroup.position.x = -cursorX / 2;
  group.add(heroGroup);

  // ---------- UNDERLINE ----------
  const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.2,
    side: THREE.DoubleSide,
  });
  const underline = new THREE.Mesh(underlineGeom, underlineMat);
  underline.position.set(-1.3, heroSpec.yBase - 0.05, 0);
  underline.scale.set(0, 1, 1);
  underline.renderOrder = 2;
  group.add(underline);

  // ---------- SUBHEAD ----------
  const subSpec = {
    text: 'Every calibre begins as a solid billet.',
    yBase: -0.65,
    fontSizePx: 40,
    fontWeight: 400,
    letterSpacing: 0.02,
    lineHeight: 1.35,
    family: 'JetBrains Mono',
  };
  const subGroup = new THREE.Group();
  let subCursorX = 0;
  for (let i = 0; i < subSpec.text.length; i++) {
    const ch = subSpec.text[i];
    const glyphInfo = ctx.fontAtlas.getGlyph(ch, {
      size: subSpec.fontSizePx,
      weight: subSpec.fontWeight,
      family: subSpec.family,
      atlas: 0,
    });
    const advance = glyphInfo.advance * (0.2 / subSpec.fontSizePx);
    const pos = {
      x: subCursorX + glyphInfo.bearing.x * (0.2 / subSpec.fontSizePx),
      y: subSpec.yBase,
      z: 0,
    };
    const mesh = createGlyphMesh(ch, glyphInfo, pos, 0);
    mesh.material.opacity = 0;
    mesh.position.y += 0.2;
    subGroup.add(mesh);
    subCursorX += advance + subSpec.letterSpacing * (0.2 / subSpec.fontSizePx);
  }
  subGroup.position.x = -subCursorX / 2;
  group.add(subGroup);

  // ---------- CAPTION ----------
  const captionSpec = {
    text: 'NOVA ATELIER / CALIBRE PROGRAM',
    yBase: 1.15,
    fontSizePx: 18,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    family: 'JetBrains Mono',
  };
  const captionGroup = new THREE.Group();
  let capCursorX = 0;
  for (let i = 0; i < captionSpec.text.length; i++) {
    const ch = captionSpec.text[i];
    const glyphInfo = ctx.fontAtlas.getGlyph(ch, {
      size: captionSpec.fontSizePx,
      weight: captionSpec.fontWeight,
      family: captionSpec.family,
      atlas: 0,
    });
    const advance = glyphInfo.advance * (0.09 / captionSpec.fontSizePx);
    const pos = {
      x: capCursorX + glyphInfo.bearing.x * (0.09 / captionSpec.fontSizePx),
      y: captionSpec.yBase,
      z: 0,
    };
    const mesh = createGlyphMesh(ch, glyphInfo, pos, 0);
    mesh.material.opacity = 1;
    captionGroup.add(mesh);
    capCursorX += advance + captionSpec.letterSpacing * (0.09 / captionSpec.fontSizePx);
  }
  captionGroup.position.x = -capCursorX / 2;
  group.add(captionGroup);

  // ---------- ANIMATIONS ----------
  const timelines = [];

  // kinetic-text (glyph entrance)
  const kineticTl = gsap.timeline();
  glyphMeshes.forEach((m, i) => {
    kineticTl.fromTo(
      m.position,
      { y: m.position.y + 0.35 },
      {
        y: m.position.y,
        duration: 0.7,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        delay: i * 0.06,
      },
      0
    );
    kineticTl.fromTo(
      m.material,
      { opacity: 0 },
      {
        opacity: 1,
        duration: 0.7,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        delay: i * 0.06,
      },
      0
    );
  });
  // weighted-settle after last glyph
  kineticTl.to(
